BEGIN TRANSACTION;
CREATE TABLE ciudades_colombia (
    id TEXT PRIMARY KEY,
    ciudad TEXT NOT NULL,
    departamento TEXT NOT NULL,
    distancia_km INTEGER NOT NULL,
    lat REAL NOT NULL,
    lng REAL NOT NULL,
    costo_envio_cop INTEGER NOT NULL,
    tiempo_estimado TEXT NOT NULL
);
CREATE TABLE domiciliarios (
    id INTEGER PRIMARY KEY,
    nombre TEXT NOT NULL,
    cedula TEXT NOT NULL UNIQUE,
    telefono TEXT NOT NULL,
    vehiculo_placa TEXT NOT NULL
);
CREATE TABLE domicilios (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo_pedido TEXT NOT NULL UNIQUE,
    fecha TEXT NOT NULL,
    cliente_nombre TEXT NOT NULL,
    cliente_cedula TEXT NOT NULL,
    direccion_entrega TEXT NOT NULL,
    destino_ciudad TEXT NOT NULL,
    distancia_km INTEGER NOT NULL,
    subtotal_compra_cop INTEGER NOT NULL,
    costo_domicilio_cop INTEGER NOT NULL,
    total_general_cop INTEGER NOT NULL,
    metodo_pago TEXT NOT NULL,
    cobro_domiciliario TEXT NOT NULL,
    codigo_cus TEXT NOT NULL,
    domiciliario_nombre TEXT NOT NULL,
    domiciliario_cedula TEXT NOT NULL,
    domiciliario_telefono TEXT NOT NULL,
    vehiculo_placa TEXT NOT NULL,
    progreso_pct INTEGER NOT NULL,
    estado_entrega TEXT NOT NULL,
    entregado INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE marcas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL UNIQUE,
    codigo TEXT NOT NULL UNIQUE
);
CREATE TABLE productos (
    id INTEGER PRIMARY KEY,
    sku TEXT NOT NULL UNIQUE,
    nombre TEXT NOT NULL UNIQUE,
    marca TEXT NOT NULL,
    categoria TEXT NOT NULL CHECK (categoria IN ('tenis','camisas','sudaderas','bolsos','accesorios')),
    subcategoria TEXT NOT NULL,
    color TEXT NOT NULL,
    precio INTEGER NOT NULL,
    material TEXT NOT NULL,
    stock INTEGER NOT NULL DEFAULT 0,
    vendidos INTEGER NOT NULL DEFAULT 0,
    tallas TEXT NOT NULL,
    imagen TEXT NOT NULL UNIQUE,
    fallback TEXT NOT NULL,
    descripcion TEXT NOT NULL
);
CREATE TABLE usuarios (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL,
    cedula TEXT NOT NULL UNIQUE,
    direccion TEXT NOT NULL,
    correo TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    rol TEXT NOT NULL DEFAULT 'cliente',
    fecha_registro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE VIEW v_resumen_almacen_por_marca AS
SELECT marca, COUNT(*) AS total_referencias, SUM(stock) AS unidades_disponibles,
       SUM(vendidos) AS unidades_vendidas, SUM(vendidos * precio) AS ingresos_estimados_cop
FROM productos GROUP BY marca;
DELETE FROM "sqlite_sequence";
COMMIT;
